function icon(n){const supplied={Results:'analytics-02.svg',Bell:'notification-01.svg',Note:'note-03.svg',Account:'user-circle-02.svg'};if(supplied[n])return `<img class="icon" src="assets/icons/${supplied[n]}" alt="">`;if(['Dashboard','Tests','Learning','Results','Settings','Subscription','Help','Logout'].includes(n))return `<img class="icon" src="assets/icons/${n}.png" alt="">`;return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.Tests}"/></svg>`}
const defaults={profile:{name:'Rahul',exam:'LanguageCert',goal:'Permanent Residency',country:'India',level:'Superior English',notifications:true},onboarded:false,tasks:[{name:'3 Speaking tests',done:true},{name:'Watch fluency exercise video',duration:'10 mins',done:false,type:'resource'},{name:'Read sentence formation resource',duration:'5 mins',done:false,type:'notes'},{name:'Book speaking session',duration:'15 mins',done:false,type:'booking'}],bookings:[],history:[]};
let saved;try{saved=JSON.parse(localStorage.getItem('verbo-v1')||'null')}catch{}let state=saved||structuredClone(defaults);let page='Dashboard',onStep=0,tab='Reading',difficulty='',status='',historyTab='Speaking Sessions',attempt=null,currentReport=null,recording=false,recorder=null,audioStream=null,recordedBlobs={},timerId=null;const modules=['Reading','Writing','Listening','Speaking','Full Test'];const targets={Writing:89,Reading:83,Listening:80,Speaking:89};const rates={Writing:85,Listening:79,Speaking:74,Reading:83};
function persist(){try{localStorage.setItem('verbo-v1',JSON.stringify(state));return true}catch{toast('Changes could not be saved. Please try again.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function modal(title,body,actions=''){const m=$('#modal');m.innerHTML=`<button class="plain close" data-action="close" aria-label="Close">✕</button><h2>${title}</h2>${body}<div class="modalactions">${actions||'<button class="primary" data-action="close">Done</button>'}</div>`;m.showModal()}
function closeModal(){$('#modal').close()}
function navigate(p){currentNote=null;page=p;currentReport=null;if(p==='Results')tab='Full Test';if(p==='Tests')tab='Reading';render();window.scrollTo(0,0)}
function shell(body){return `<div class="shell"><aside class="sidebar"><div class="brand"><img class="brand-logo" src="assets/icons/logo.png" alt="">Verbo</div><div class="nav-caption">MAIN</div>${['Dashboard','Tests','Learning','Results'].map(n=>`<button data-nav="${n}" class="navbutton ${page===n?'selected':''}">${icon(n)}${n}</button>`).join('')}<div class="nav-caption">ACCOUNT</div>${['Settings','Subscription','Help'].map(n=>`<button data-nav="${n}" class="navbutton ${page===n?'selected':''}">${icon(n)}${n}</button>`).join('')}<div class="sidebar-footer"><button class="navbutton sidebar-profile" data-nav="Settings" aria-label="Your profile and settings"><img class="avatar" src="assets/icons/profile_icon.svg" alt=""><span><span class="profile-name">${escape(state.profile.name==='Rahul'?'Rahul Kumar':state.profile.name)}</span><span class="profile-plan">${escape(state.plan||'Practice')}</span></span></button><div class="profile-divider"></div><button data-action="logout" class="navbutton logout">${icon('Logout')}Log Out</button></div></aside><header class="topbar"><h1>${page}</h1><div class="top-actions"><button class="plain" data-action="notifications" aria-label="Notifications">${icon('Bell')}</button></div></header><main class="content">${body}</main><nav class="mobile-nav" aria-label="Main navigation">${['Dashboard','Tests','Learning','Results','Settings'].map(n=>`<button data-nav="${n}" class="${page===n?'selected':''}">${icon(n)}${n}</button>`).join('')}</nav></div>`}
function render(){if(attempt){renderTest();return}if(!state.onboarded){onboard();return}const views={Dashboard:dashboard,Tests:tests,Learning:learning,Results:results,Settings:settings,Subscription:subscription,Help:help};app.innerHTML=shell(views[page]());}
function dashboard(){if(state.freshStart)return freshDashboard();return `<h2 class="greeting">Welcome Back, <span class="purple">${escape(state.profile.name)}.</span></h2><h3>Your Progress</h3><div class="dashboard-grid"><div><div class="scores">${Object.entries(rates).map(([m,v])=>`<article class="panel scorecard"><div class="row"><h3>${m}</h3><span class="pill">Last 7 tests</span></div><div class="score ${v>=targets[m]?'purple':''}">${v}% <small>/ ${targets[m]}%</small></div><div class="bar"><span style="width:${Math.min(v/targets[m]*100,100)}%"></span></div><span class="${v>=targets[m]?'purple':''}">${v>=targets[m]?'Target Met!':`${targets[m]-v} ${targets[m]-v===1?'point':'points'} to go`}</span></article>`).join('')}</div><section class="panel chart-panel"><div class="row"><span>Estimated Score <button class="link" data-action="score-info" aria-label="About score estimates">ⓘ</button></span><span class="pill">Last 7 tests</span></div><div class="row"><div class="score">82% <span class="pill purple" style="font-size:27px">C1</span></div><small>Target Goal<br><strong>90% <span class="target-badge">C2</span></strong></small></div><svg class="chart" viewBox="0 0 650 180" role="img" aria-label="Recent full mock scores rise from 68 to 82 percent"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#cecbff"/><stop offset="1" stop-color="#fff"/></linearGradient></defs><path d="M10 168L105 108L220 108L300 125L390 124L480 91L535 91L635 55L635 175H10Z" fill="url(#fade)"/><path d="M10 168L105 108L220 108L300 125L390 124L480 91L535 91L635 55" fill="none" stroke="#6057ff" stroke-width="2"/><path d="M10 30H635" stroke="#333" stroke-dasharray="2 2"/><path d="M10 18V175H635" fill="none" stroke="#bbb"/>${[[105,108],[220,108],[300,125],[390,124],[480,91],[535,91],[635,55]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="#6057ff" stroke-width="2"><title>Full test ${i+1}</title></circle>`).join('')}</svg><button class="link" data-nav="Results">View your test history ${chev('right')}</button></section></div><div class="stack dashboard-side"><section class="panel"><p>Your weekly tasks</p><h2 class="task-title">Speaking</h2><p class="muted">${state.tasks.filter(t=>t.done).length} of ${state.tasks.length} Tasks Completed</p><hr class="divider">${state.tasks.map((t,i)=>`<div class="task ${t.done?'done':''}"><input type="checkbox" data-task="${i}" aria-label="Complete ${escape(t.name)}" ${t.done?'checked':''}><button data-task-open="${i}"><span class="task-name">${escape(t.name)}</span><span class="duration">${t.duration||''}</span></button></div>`).join('')}</section><section class="panel"><p>Weekly Test Streak</p><h2 class="task-title">3 Days 🔥</h2><div class="panel black row" style="padding:14px 20px">Tests Completed: <strong>${3+state.history.length}/10</strong></div><div class="week">${['✓','✓','✓','T','F','S','S'].map((d,i)=>`<span class="${i<3?'complete':''}">${i<3?'<i class="ui-tick" aria-hidden="true"></i>':d}</span>`).join('')}</div></section></div></div>`}
function tabbar(){return `<div class="tabs">${modules.map(m=>`<button data-tab="${m}" class="${tab===m?'active':''}">${m}</button>`).join('')}</div>`}
const titles={Reading:['Reading mastery 1','Reading mastery 2','Reading mastery 3','Meaning in context','Find the key information','Main ideas and supporting details'],Writing:['International tourism','Develop a clear argument','Structure your response'],Listening:['Listen for the key detail','A workshop announcement','Everyday conversations'],Speaking:['Express and develop your ideas','Link your ideas naturally','Support your opinion'],'Full Test':['Full Test 1','Full Test 2','Full Test 3']};
const testFilters=new Set();let testFilterOpen=false;
function tests(){const names=[...titles[tab],...Array.from({length:10},(_,i)=>`${tab==='Full Test'?'Full mock':tab+' practice'} ${titles[tab].length+i+1}`)];const levels=['Hard','Medium','Easy'];const items=names.map((name,i)=>({name,i,level:levels[i%3],status:state.history.some(r=>r.title===name)?'Completed':'New'})).filter(t=>(!levels.some(l=>testFilters.has(l))||testFilters.has(t.level))&&(!['New','Completed'].some(l=>testFilters.has(l))||testFilters.has(t.status)));return `<section class="test-library"><h2 class="greeting">Your Test Library</h2><div class="test-library-toolbar">${tabbar()}<div class="test-filter"><button class="secondary" data-action="test-filter-toggle" aria-expanded="${testFilterOpen}" aria-controls="test-filter-options"><svg class="chevron" viewBox="0 0 20 20" fill="none" stroke="currentColor" aria-hidden="true"><path d="M2 3h16l-6 7v7l-4-2v-5Z"/></svg>Filter ${testFilters.size?`<span class="pill purple">${testFilters.size}</span>`:''}${chev()}</button><div class="test-filter-options" id="test-filter-options" ${testFilterOpen?'':'hidden'}><div class="filter-label">DIFFICULTY</div>${levels.map(l=>`<label><input type="checkbox" data-test-filter="${l}" ${testFilters.has(l)?'checked':''}>${l}</label>`).join('')}<div class="filter-label filter-divider">STATUS</div>${['New','Completed'].map(l=>`<label><input type="checkbox" data-test-filter="${l}" ${testFilters.has(l)?'checked':''}>${l}</label>`).join('')}<div class="filter-footer"><button class="clear-filter-button" data-action="clear-test-filters">Clear filters</button></div></div></div></div><div class="row filterrow"><div class="filter-chips">${[...testFilters].map(f=>`<button class="filterchip" data-remove-filter="${f}" aria-label="Remove ${f} filter">${f} ×</button>`).join('')}</div><span class="muted">Showing ${items.length} Tests</span></div><div class="grid3">${items.map(t=>`<article class="panel test-card"><span class="pill ${t.level.toLowerCase()}">${t.level}</span> <span class="pill ${t.status==='New'?'new':'completed'}">${t.status}</span><h3>${t.name}</h3><small>${tab==='Full Test'?'4 Modules · 12 Questions · 25 Mins':tab==='Writing'?'2 Questions · 10 Mins':tab==='Speaking'?'4 Questions · 5 Mins':'3 Questions · 5 Mins'}</small><br><button class="primary" data-start="${tab}" data-title="${t.name}">${t.status==='Completed'?'Retake Test':'Start Test'}</button></article>`).join('')}</div>${!items.length?'<div class="panel empty"><img class="empty-state-art" src="assets/empty-search.svg" alt="">No tests match these filters.<br><button class="secondary" data-action="clear-test-filters">Clear filters</button></div>':''}</section>`}
const resourceNames=['Language cert oral exam','Language cert listening module','Language cert writing prep','Prepare for your speaking session','Know your exam format'];
const resourceImages=['resource-speaking.jpg','resource-listening.jpg','resource-writing.jpg','resource-tutor.jpg','resource-exam.jpg'];
function resources(){return `<div class="carousel">${resourceNames.map((n,i)=>`<button class="resource" data-resource="${i}"><img src="assets/${resourceImages[i]}" alt=""><span>${n}<br><small style="color:white">${[18,20,15,10,12][i]} Mins · ${i===2?'Read':'Watch'}</small><br><span class="pill" style="position:static;display:inline-block;background:white;color:#444;padding:3px 8px;margin-top:8px">${['Speaking','Listening','Writing','Speaking','Full Test'][i]}</span></span></button>`).join('')}</div>`}
function learningArrows(target){return `<button class="chevron-button" data-carousel="-1" data-carousel-target="${target}" aria-label="Previous ${target==='learning-schedule'?'sessions':'resources'}"><img src="assets/chevron-left.svg" alt=""></button><button class="chevron-button" data-carousel="1" data-carousel-target="${target}" aria-label="Next ${target==='learning-schedule'?'sessions':'resources'}"><img src="assets/chevron-right.svg" alt=""></button>`}
let scheduleRange='Today';
function learningSchedule(){
 const today=new Date();today.setHours(0,0,0,0);
 const dateAt=n=>{const d=new Date(today);d.setDate(d.getDate()+n);return d};
 const end=new Date(today);if(scheduleRange==='This week')end.setDate(end.getDate()+6-((end.getDay()+6)%7));if(scheduleRange==='This month')end.setMonth(end.getMonth()+1,0);
 const rows=[['Speaking Session','1PM – 1:15PM','Susan Walsh','One on One',0],['Writing Part 2','4PM – 4:30PM','Damien Strand','Lecture',0],['Reading Part 3','5PM – 6:30PM','Damien Strand','Lecture',0],['Listening Practice','10AM – 11AM','Kriti K','Lecture',1],['Speaking Confidence','2PM – 2:30PM','Susan Walsh','One on One',2],['Writing Workshop','4PM – 5PM','Damien Strand','Lecture',4],['Reading Strategies','11AM – 12PM','Damien Strand','Lecture',7],['Listening for Details','3PM – 4PM','Kriti K','Lecture',10],['Full Mock Review','10AM – 11AM','Susan Walsh','Lecture',14]].map(r=>({title:r[0],time:r[1],tutor:r[2],type:r[3],date:dateAt(r[4])}));
 rows.push(...state.bookings.map(b=>({title:b.module+' Session',time:b.time.split(' · ').pop(),tutor:b.tutor,type:'One on One',date:new Date(b.date+'T00:00:00')})));
 return rows.filter(r=>r.date>=today&&r.date<=end).sort((a,b)=>a.date-b.date);
}
let currentNote=null;
function learning(){if(currentNote!==null)return lectureNotePage(currentNote);const sessions=learningSchedule();return `<div class="learning-page"><h2 class="greeting">Keep building on your practise, <span class="purple">${escape(state.profile.name)}.</span></h2><div class="row report-section-heading"><h3>My Schedule <span class="pill purple">${sessions.length}</span></h3><div class="row"><button class="secondary" data-action="booking">Book Session <svg class="chevron" viewBox="0 0 20 20" fill="none" stroke="currentColor" aria-hidden="true"><rect x="3" y="5" width="14" height="12" rx="2"/><path d="M3 9h14M6 2v5M14 2v5"/></svg></button><div class="study-dropdown schedule-dropdown"><button class="secondary study-trigger" data-action="schedule-toggle" aria-expanded="false" aria-controls="schedule-options">${scheduleRange} ${chev()}</button><div class="study-options" id="schedule-options" hidden>${['Today','This week','This month'].map(o=>`<button data-schedule-range="${o}" aria-pressed="${o===scheduleRange}">${o}${o===scheduleRange?'<span class="ui-tick" aria-hidden="true"></span>':''}</button>`).join('')}</div></div></div></div><div class="carousel" id="learning-schedule">${sessions.map((r,i)=>`<article class="session black"><h3>${escape(r.title)}</h3><p class="session-date">${r.date.toLocaleDateString('en-AU',{weekday:'long',day:'numeric',month:'long'})}</p><p>${escape(r.time)}</p><span class="pill">${r.type}</span><div class="tutor"><img src="assets/${r.tutor==='Susan Walsh'?'susan.svg':r.tutor==='Kriti K'?'kriti.svg':'damien-writing.svg'}" alt=""><div>${escape(r.tutor)}<br><small>${r.tutor==='Susan Walsh'?'Mentor':'Tutor'}</small></div></div><button class="primary" data-join="${escape(r.title)}" ${i===0?'':'disabled'}>Join</button></article>`).join('')}</div><section class="recommendation row"><div><span class="purple">Recommended this week</span><h3>Speaking – Link your ideas naturally</h3><p>Intermediate · 5 mins · 4 questions</p></div><button class="primary" data-start="Speaking" data-title="Link your ideas naturally">Start Test</button></section><div class="row report-section-heading"><h3>Resources tailored for you <span class="pill purple">${resourceNames.length}</span></h3></div><div id="learning-resources">${resources()}</div><h3 style="margin-top:32px">Your Class History</h3><div class="tabs">${['Notes','Recordings','Speaking Sessions'].map(t=>`<button data-history-tab="${t}" class="${historyTab===t?'active':''}">${t}</button>`).join('')}</div><div class="history report-modules learning-history">${historyTab!=='Speaking Sessions'?lectureHistory():[10,9,8].map((n,i)=>`<details class="module-detail"><summary><div class="module-row"><div><strong>${historyTab==='Speaking Sessions'?'Session '+n:historyTab==='Notes'?'Speaking notes '+n:'Session recording '+n}</strong><small>${historyTab==='Speaking Sessions'?'One on One':historyTab==='Notes'?'Lecture notes':'Lecture recording'}</small></div><div class="history-tutor"><img src="assets/susan.svg" alt="Susan Walsh"><div>Susan Walsh<small>Mentor</small></div></div><div>${['September 10th','September 3rd','August 29th'][i]}<small>${['6PM – 6:15PM','7PM – 7:15PM','2PM – 2:15PM'][i]}</small></div><div>Session Score<small>${[75,71,68][i]}%</small></div><span class="purple view-label">View ${chev()}</span></div></summary><div class="detail"><section class="panel black"><h3>Mentor Feedback</h3><p>You answered directly and supported your preference with practical reasons. The ideas are relevant, but the pauses make them sound separate. Try a linking phrase before adding your next point.</p></section><div class="grid2" style="margin-top:18px"><div class="audio-panel mentor-audio"><div class="row audio-heading"><small>Session feedback · Audio preview</small><button class="secondary" data-action="mentor-transcript">View Transcript</button></div>${wave()}<div class="audio-track"></div><div class="row"><small>Mentor feedback</small><small>Sample audio</small></div><button class="secondary" data-action="mentor-play" aria-label="Play mentor feedback">▷ Play</button></div><button class="resource mentor-resource" data-resource="3"><img src="assets/resource-tutor.jpg" alt="Speaking practice with a tutor"><b class="mentor-badge">Recommended by mentor</b><span>Linking Words and Phrases<br><small>20 Mins · Watch</small><br><em>Speaking</em></span></button></div></div></details>`).join('')}</div></div>`}
const lectureTitles=['Writing Task 2 – Sample Answers','Speaking Samples – Roleplay + Describe Image','Language Cert Essay Writing Structure – Fully Explained'];
const lectureDates=['12 December 2025','10 December 2025','8 December 2025'];
const lectureTimes=['4PM – 4:30PM','6PM – 6:30PM','2PM – 2:30PM'];
function lectureMeta(i){return `<div class="history-tutor"><img src="assets/${i===1?'susan.svg':'damien-writing.svg'}" alt=""><div>${i===1?'Susan Walsh':'Damien Strand'}<small>Tutor</small></div></div><div>Completed ${lectureDates[i]}<small>${lectureTimes[i]}</small></div>`}
function lectureRecording(i){return `<div class="detail"><div class="grid2"><div class="audio-panel mentor-audio"><div class="row audio-heading"><small>Lecture recording ${i+1}</small><button class="secondary" data-lecture-transcript="${i}">View Transcript</button></div>${wave()}<div class="audio-track"></div><div class="row"><small>00:00</small><small>30:00</small></div><button class="secondary" data-lecture-play="${i}">▷ Play recording</button></div><button class="resource mentor-resource" data-resource="${i===1?3:2}"><img src="assets/${i===1?'resource-tutor.jpg':'resource-writing.jpg'}" alt=""><b class="mentor-badge">Recommended by tutor</b><span>${i===1?'Linking Words and Phrases':'Structure your response'}<br><small>15 Mins · ${i===1?'Watch':'Read'}</small></span></button></div></div>`}
function lectureHistory(){return lectureTitles.map((t,i)=>historyTab==='Notes'?`<article class="lecture-note-row"><div><strong>${t}</strong><small>Lecture notes · ${i+1}</small></div>${lectureMeta(i)}<button class="link view-label" data-note="${i}">View ${chev('right')}</button></article>`:`<details class="module-detail lecture-recording"><summary><div class="module-row"><div><strong>${t}</strong><small>Lecture recording · ${i+1}</small></div>${lectureMeta(i)}<span class="purple view-label">View ${chev()}</span></div></summary>${lectureRecording(i)}</details>`).join('')}
function lectureNotePage(i){const sections=i===1?[['Start with a direct response','Answer the roleplay prompt directly. Explain your choice with a practical reason, then add an example.'],['Describe the image in order','Begin with an overview. Identify the main subjects, describe their relationship and finish with the most important detail.'],['Connect your ideas','Use phrases such as “Another reason is” and “For example” to link your points. Practise short responses without rushing.']]:[['Plan before you write','Identify the question, decide your main argument and outline two supporting ideas before drafting your response.'],['Build each paragraph around one idea','Start with a clear topic sentence. Explain your point, support it with a specific example and connect it back to the question.'],['Sample paragraph','Car-free city centres can make everyday journeys safer and more pleasant. When streets prioritise pedestrians and cyclists, residents have more space to move without competing with traffic. For example, protected routes near schools can encourage families to cycle short distances. This approach works best when reliable public transport remains available.'],['Review your response','Check that you have answered every part of the task. Remove repetition, vary sentence structures and leave time to check grammar and punctuation.']];return `<div class="lecture-note-page"><button class="report-back plain" data-action="backnotes">${chev('left')}Back to your class history</button><header class="lecture-note-header"><span class="purple note-kicker">LECTURE NOTES · ${i+1}</span><h2>${lectureTitles[i]}</h2><div class="lecture-note-meta">${lectureMeta(i)}</div></header><article class="lecture-note-content"><p class="note-intro">Key ideas and examples from this lecture, ready to revisit as you practise.</p>${sections.map(([h,p])=>`<section><h3>${h}</h3><p>${p}</p></section>`).join('')}</article></div>`}
const seedHistory=[{title:'Full Test 1',module:'Full Test',date:'September 3rd',score:82,full:true,scores:{Writing:86,Reading:90,Listening:80,Speaking:72}},{title:'Full Test 2',module:'Full Test',date:'August 29th',score:78,full:true,scores:{Writing:80,Reading:80,Listening:80,Speaking:72}},{title:'Full Test 3',module:'Full Test',date:'August 23rd',score:75,full:true,scores:{Writing:76,Reading:80,Listening:72,Speaking:72}},...['Reading','Writing','Listening','Speaking'].map((m,i)=>({title:titles[m][0],module:m,date:'September 3rd',score:[90,86,80,72][i],scores:{[m]:[90,86,80,72][i]}}))];
const feedback={Writing:['Vary sentence structures to avoid repetitive phrasing.','Include specific percentages or data values to support comparisons.'],Reading:['Practise common word combinations in context.','Look for evidence in the passage before selecting an answer.'],Listening:['Summarise short recordings in your own words.','Listen for the whole time expression and practical details.'],Speaking:['Reduce long pauses with short, timed responses.','Use linking phrases to connect your ideas smoothly.','Support each answer with a reason and an example.']};
function results(){if(currentReport)return report(currentReport);const all=[...state.history,...(state.freshStart?[]:seedHistory)];const rows=all.map((r,i)=>({...r,id:i})).filter(r=>r.module===tab);return `<section class="results-library"><div class="row"><h3>Your Test History</h3></div>${tabbar()}<div class="row filterrow"><span class="muted">Showing ${rows.length} Tests</span></div><div class="stack">${rows.map(r=>`<article class="panel result-row"><div><strong>${escape(r.title)}</strong><br><small>${r.full?'4 Modules':r.module}</small></div><div>${r.date}<br><small>Completed</small></div><div>Test Score<br><small>${r.score==null?'Feedback available':r.score+'%'}</small></div><button class="link" data-report="${r.id}">View ${chev('right')}</button></article>`).join('')||'<div class="panel empty"><img class="empty-state-art" src="assets/empty-results.svg" alt="">Complete a test to see your results here.</div>'}</div></section>`}
function chev(direction='down'){return `<svg class="chevron ${direction}" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 6l4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function report(r){const ms=r.full?['Writing','Reading','Listening','Speaking']:[r.module];const sample=!r.answers;const parts={Writing:2,Reading:5,Listening:4,Speaking:4},totals={Writing:2,Reading:30,Listening:30,Speaking:4},times={Writing:'49:02',Reading:'48:22',Listening:'38:05',Speaking:'13:58'};return `<div class="report-page"><button class="report-back plain" data-action="backresults">${chev('left')}Back to your test history</button><section class="panel report-overview"><div class="row"><div><span>Overview</span><h3>${escape(r.title)}</h3></div><div class="report-tags"><span class="pill hard">Hard</span><span class="pill">Completed ${r.date}</span><span class="pill">Total Time: ${sample?'2:29:27':r.elapsed||'—'}</span></div></div><div class="summary-scores" style="grid-template-columns:repeat(${ms.length+1},minmax(0,1fr))">${ms.map(m=>`<div>${m}<div class="score">${r.scores?.[m]??'—'}${r.scores?.[m]!=null?'%':''} <small>/ ${targets[m]}%</small></div><small class="${r.scores?.[m]>=targets[m]?'purple':''}">${r.scores?.[m]==null?'Awaiting assessment':r.scores[m]>=targets[m]?'Target Met!':targets[m]-r.scores[m]+' points to go'}</small></div>`).join('')}<div>Estimated Score <button class="link" data-action="score-info" aria-label="About this score">ⓘ</button><div class="score">${r.score??'—'}${r.score!=null?'%':''}${sample?'<span class="pill purple sample-level">C1</span>':''}</div></div></div></section><div class="row report-section-heading"><h3>Module Results</h3></div><div class="history report-modules">${ms.map(m=>{const total=sample?totals[m]:questions[m].length;const answered=sample?(['Reading','Listening'].includes(m)?Math.round(r.scores[m]/100*total):total):questions[m].filter((q,i)=>['Reading','Listening'].includes(m)?r.answers[m+'-'+i]===q[2]:!!r.answers[m+'-'+i]).length;return `<details class="module-detail"><summary><div class="module-row"><div><strong>${m}</strong><small>${sample?parts[m]+' Parts · ':''}${total} Questions</small></div><div>Time Taken<small>${sample?times[m]:'—'}</small></div><div>${['Reading','Listening'].includes(m)?'Answered Correctly':'Answered'}<small>${answered}/${total}</small></div><div>Score<small>${r.scores?.[m]!=null?r.scores[m]+'%':'Awaiting assessment'}</small></div><span class="purple view-label">View ${chev()}</span></div></summary><div class="detail">${answerReview(r,m)}<button class="secondary" data-start="${m}" data-title="${titles[m][0]}">Try another ${m.toLowerCase()} test ${chev('right')}</button></div></details>`}).join('')}</div><h3 class="report-section-heading">AI Feedback</h3><div class="grid2 feedback">${(r.full?['Listening','Writing','Speaking','Reading']:ms).map(m=>`<section class="panel black"><h3>${m}</h3><ul>${feedback[m].map(t=>`<li>${t}</li>`).join('')}</ul></section>`).join('')}</div><div class="row report-section-heading"><h3>Recommended Practice <span class="pill purple">5</span></h3><div class="row"><button class="secondary" data-action="scheduleall">Add all to weekly tasks</button></div></div><div class="report-resources report-practice-grid"><div class="practice-grid" id="report-carousel"><button class="resource" data-resource="0"><img src="assets/resource-speaking.jpg" alt=""><span>Language cert oral exam<br><small>18 Mins · Watch</small></span></button>${['Speaking Samples','Writing Formula','Prediction Practice','Exam Format'].map((n,i)=>`<article class="session black"><h3>${n}</h3><p>${i===0?'Notes':'Recording'}</p><span class="pill">Lecture</span><div class="tutor"><img src="assets/${i===1?'kriti.svg':'damien-writing.svg'}" alt=""><div>${i===1?'Jamila Kishor':'Damien Strand'}<br><small>Tutor</small></div></div><button class="primary" data-resource="${i===0?3:i===1?2:4}">View ${i===0?'Notes':'Recording'}</button></article>`).join('')}</div></div></div>`}

function settings(){const prefs=state.preferences||{};return `<h2 class="greeting">Make Verbo <span class="purple">work for you.</span></h2><p class="page-subtitle">Your preparation, account and notification preferences.</p><div class="settings-context"><span>Personal preferences</span><span><img class="avatar" src="assets/icons/profile_icon.svg" alt="">${escape(state.profile.name)} · ${escape(state.profile.exam)}</span></div><section class="settings-card"><header><span class="settings-icon">${icon('Bell')}</span><div><h3>Keep the right things in view</h3><p>Choose the updates that support your preparation.</p></div></header>${[['practice','Practice reminders','A gentle reminder to make time for your weekly tasks.'],['sessions','Upcoming classes and sessions','A heads-up before a booked class or one-to-one session.'],['feedback','New results and tutor feedback','Know when your latest feedback is ready to review.'],['digest','Weekly progress summary','A weekly look at your practice, progress and next steps.']].map(([id,title,desc],i)=>`<label class="settings-row"><div><strong>${title}</strong><p>${desc}</p></div><input class="switch" type="checkbox" data-pref="${id}" aria-label="${title}" ${(prefs[id]??i<3)?'checked':''}></label>`).join('')}<div class="settings-email"><label for="settings-email">Notification email</label><input id="settings-email" value="rahul@example.com" readonly><small>Demo account · no emails will be sent.</small></div><footer><button class="primary" data-action="savepreferences">Save preferences</button></footer></section><section class="settings-card"><header><span class="settings-icon">${icon('Note')}</span><div><h3>Your preparation</h3><p>Keep your study plan aligned with your goal.</p></div></header><div class="settings-row"><div><strong>${escape(state.profile.exam)}</strong><p>${escape(state.profile.goal)} · ${escape(state.profile.level)}</p></div><button data-settings-demo="Preparation goals">Edit goals</button></div><div class="settings-row"><div><strong>Weekly study goal</strong><p>A manageable rhythm to keep your preparation moving.</p></div><div class="study-dropdown"><button class="secondary study-trigger" data-action="study-toggle" aria-expanded="false" aria-controls="study-options"><span>${state.profile.studyGoal||'3 days a week'}</span>${chev()}</button><div class="study-options" id="study-options" hidden>${['3 days a week','5 days a week','Every day'].map(option=>`<button data-study-goal="${option}" aria-pressed="${(state.profile.studyGoal||'3 days a week')===option}">${option}${(state.profile.studyGoal||'3 days a week')===option?'<span class="ui-tick" aria-hidden="true"></span>':''}</button>`).join('')}</div></div></div></section><section class="settings-card"><header><span class="settings-icon">${icon('Account')}</span><div><h3>Account and privacy</h3><p>Manage your account preferences in one place.</p></div></header><div class="settings-row"><div><strong>Password</strong><p>Your demo credentials are prefilled on the login screen.</p></div><button data-settings-demo="Password settings">Change password</button></div><div class="settings-row"><div><strong>Your learning data</strong><p>Review the information associated with your preparation.</p></div><button data-settings-demo="Learning data">Manage data</button></div></section>`}

let billing='monthly';
const plans=[{name:'Starter',price:0,description:'Find your starting point.',features:['4 module practice tests each month','1 full mock test each month','Score breakdown and basic feedback','A selection of learning resources']},{name:'Practice',price:25,description:'Build a consistent practice routine.',features:['Unlimited module and full mock tests','Detailed feedback and weekly tasks','Your complete progress history','All videos, notes and class recordings']},{name:'Guided',price:65,description:'Move forward with personal support.',features:['Everything in Practice','2 one-to-one tutor sessions each month','Personalised speaking and writing feedback','Live group classes and session notes']}];
function subscription(){return `<section class="pricing"><div class="pricing-intro"><h2>Your goal. Your pace. <span class="purple">Your plan.</span></h2><p>From your first practice test to focused tutor support.<br>Choose the preparation that works for you.</p></div><div class="billing"><div role="group" aria-label="Billing period"><button data-billing="monthly" aria-pressed="${billing==='monthly'}">Monthly</button><button data-billing="yearly" aria-pressed="${billing==='yearly'}">Yearly</button></div><span>Save 20% with yearly billing</span></div><div class="plan-grid">${plans.map((p,i)=>`<article class="plan ${i===1?'featured':''}"><div class="row"><h3>${p.name}</h3>${i===1?'<span class="pill purple">For regular practice</span>':''}</div><p>${p.description}</p><div class="price">$${billing==='yearly'?p.price*.8:p.price}<small> AUD / month</small></div><p class="billing-detail">${!p.price?'Free to explore.':billing==='yearly'?`$${p.price*12*.8} AUD billed yearly.`:'Billed monthly. Cancel before your next renewal.'}</p><button class="${i===1?'primary':''}" data-plan="${p.name}">${state.plan===p.name?'Selected plan':'Choose '+p.name}<span>${chev('right')}</span></button><ul>${p.features.map(f=>`<li><span class="ui-tick" aria-hidden="true"></span>${f}</li>`).join('')}</ul></article>`).join('')}</div><p class="pricing-note">Prototype plans and illustrative prices. Selecting a plan previews the experience; you won’t be charged.</p></section>`}

function help(){const faqs=[['How do I get started with Verbo?','Choose your exam and preparation goal during onboarding. Then take a practice test to understand your starting point and use your results to choose what to work on next.'],['Can I resume a test after exiting?','Exiting ends the current attempt. To try again, start a new test from your test library. Submitted attempts are available in Results.'],['How do I understand my test results?','Open Results and select an attempt. You can compare your module scores with your targets, view your answers and find recommended practice. Scores and targets in this prototype are illustrative.'],['Where can I find my lecture notes and recordings?','Open Learning and scroll to Your Class History. Choose Notes to read a lecture, or Recordings to open its recording and recommended practice.'],['How do I book a tutor session?','Select Book Session on the Learning page. Choose a module, tutor, date and available time, then add what you would like to work on. Bookings in this prototype are demonstrations.'],['Where can I find feedback from my speaking sessions?','Go to Learning, then choose Speaking Sessions under Your Class History. Expand a session to see its feedback, audio preview and recommended practice.'],['How do weekly tasks work?','Add recommended practice from a result to your weekly tasks. Your Dashboard keeps those tasks together so you can track what you have completed.'],['Can I change my preparation goals or subscription?','You can explore your preparation preferences in Settings and compare plans in Subscription. Account changes and payments are not connected in this prototype.']];return `<section class="help-page"><header class="help-intro"><span class="help-eyebrow">VERBO SUPPORT</span><h2>How can we <span class="purple">help you?</span></h2><p>Find answers about your preparation, tests and learning.<br>Need a little more guidance? We’re here to help.</p><div class="help-actions"><button class="secondary" data-action="help-unavailable">Explore the guide ${chev('right')}</button><button class="primary" data-action="help-unavailable">Contact support</button></div></header><section class="help-faq" aria-labelledby="help-faq-title"><div class="help-section-heading"><h3 id="help-faq-title">Frequently asked questions</h3><span>${faqs.length} answers to get you started</span></div>${faqs.map(([q,a],i)=>`<details class="help-question" ${i===0?'open':''}><summary><span>${q}</span>${chev()}</summary><div class="help-answer"><p>${a}</p></div></details>`).join('')}</section><footer class="help-contact"><div><h3>Still have a question?</h3><p>Get help with your account or preparation.</p></div><button class="link" data-action="help-unavailable">Get in touch ${chev('right')}</button></footer></section>`}

const countryList=[['Australia','AU'],['Bangladesh','BD'],['Brazil','BR'],['Canada','CA'],['China','CN'],['France','FR'],['Germany','DE'],['Iceland','IS'],['India','IN'],['Indonesia','ID'],['Iran','IR'],['Iraq','IQ'],['Ireland','IE'],['Italy','IT'],['Japan','JP'],['Malaysia','MY'],['Nepal','NP'],['New Zealand','NZ'],['Pakistan','PK'],['Philippines','PH'],['Singapore','SG'],['South Africa','ZA'],['South Korea','KR'],['Sri Lanka','LK'],['United Arab Emirates','AE'],['United Kingdom','GB'],['United States','US'],['Vietnam','VN']];
function countryFlag(name){const code=countryList.find(c=>c[0]===name)?.[1]||'IN';return `<img class="country-flag" src="https://www.untitledui.com/images/flags/rectangle/${code}.svg" alt="">`}
document.addEventListener('click',e=>{const menu=$('#country-menu');if(menu&&!e.target.closest('.country-picker')){menu.hidden=true;$('#country').setAttribute('aria-expanded','false')}});
document.addEventListener('keydown',e=>{const menu=$('#country-menu');if(!menu||menu.hidden)return;if(e.key==='Escape'){menu.hidden=true;$('#country').setAttribute('aria-expanded','false');$('#country').focus()}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const items=[...menu.querySelectorAll('[data-country]:not([hidden])')],i=items.indexOf(document.activeElement);items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}});
function onboard(){if(onStep===0){app.innerHTML=`<main class="onboard login-layout"><div class="login-art"><img class="hero" src="assets/welcome.webp" alt="Three friendly geometric characters"><h1>A clearer path.<br>A more confident you.</h1><p>Your exam, your goal, your next step.</p></div><section class="login"><div class="brand"><img class="brand-logo" src="assets/icons/logo.png" alt="">Verbo</div><h2 style="text-align:center;font-weight:400">Please enter your details.</h2><p class="demo-note">Prototype only — please don’t enter personal details. Demo details are prefilled and reset after editing.</p><form id="login-form" class="form"><label for="email">Email</label><input id="email" type="email" value="rahul@example.com" autocomplete="off"><label for="password">Password</label><input id="password" type="password" value="VerboDemo123!" autocomplete="off"><div class="row"><label><input type="checkbox" style="width:auto"> Remember Me</label><button type="button" class="link" data-action="forgot">Forgot Password?</button></div><button class="primary" type="submit">Log In</button><button type="button" style="width:100%;margin-top:14px" data-action="signup"><span class="google-g" aria-hidden="true">G</span>Log In with Google</button></form><p style="text-align:center;margin:24px 0 0">Don’t have an account? <button class="link" data-action="signup">Sign Up</button></p></section></main>`;return}let body='';if(onStep===-1)body=`<div class="verification-copy"><div class="mail-symbol" aria-hidden="true"><img src="assets/icons/mail-01.svg" alt=""></div><h2>You’ve got mail.</h2><p>Confirm your email to start your Verbo journey.</p><p class="verification-email">rahul@example.com</p><p class="demo-note">This is a prototype — no email has been sent.<br>Select Next to preview the next step.</p></div>`;if(onStep===1)body=`<h2>Hi ${escape(state.profile.name)}, welcome to <span style="color:#5C5FFF">Verbo.</span></h2><p>Start by telling us which English exam you’re preparing for.</p>${['IELTS','LanguageCert','CELPIP','Cambridge C1 Advanced'].map(x=>choice('exam',x,x==='CELPIP'?'A computer-based English test focused on real-world communication.':'A four-skill English test covering Listening, Reading, Writing and Speaking.')).join('')}`;if(onStep===2)body=`<h2>What are you preparing for?</h2><p>Tell us your goal so we can personalise your experience.</p>${[['Permanent Residency','Meet English requirements for your permanent residency application.'],['University','Meet English requirements for admission to an English-speaking university or college.'],['Student or Work Visa','Meet English requirements for a student or work visa application.'],['Work Requirements','Demonstrate your English proficiency for a job, registration or workplace requirement.']].map(([x,d])=>choice('goal',x,d)).join('')}`;if(onStep===3)body=`<h2>Where are you from?</h2><p>Your nationality helps us understand which English requirements may apply to your needs.</p><label for="country">Nationalities</label><div class="country-picker"><button id="country" class="country-trigger" data-action="countries" aria-expanded="false" aria-controls="country-menu">${countryFlag(state.profile.country)}<span>${escape(state.profile.country)}</span>${chev('down')}</button><div id="country-menu" class="country-menu" hidden><div class="country-search-wrap"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg><input id="country-search" placeholder="Search countries" aria-label="Search countries" autocomplete="off"></div><div class="country-options">${countryList.map(([name])=>`<button data-country="${name}" class="country-option">${countryFlag(name)}<span>${name}</span>${name===state.profile.country?'<i class="ui-tick"></i>':''}</button>`).join('')}<p id="country-empty" hidden>No countries found.</p></div></div></div>`;if(onStep===4)body=`<h2>Choose your target score.</h2><p>Based on your goal of ${escape(state.profile.goal)}, Verbo recommends focusing on the English levels that can contribute additional points to your application.</p>${['Superior English','Proficient English'].map(x=>choice('level',x,x==='Superior English'?'20 Migration Points · Level C2':'10 Migration Points · Level C1',`<div class="target-table"><div class="row"><small style="color:#ccc">Skill</small><small style="color:#ccc">Target Score</small></div><hr>${Object.entries(targets).map(([m,v])=>`<div class="row target-score-row"><span>${m}</span><i class="score-leader" aria-hidden="true"></i><span>${x==='Superior English'?v:Math.max(65,v-15)}</span></div>`).join('')}</div>`)).join('')}`;if(onStep===5)body=`<h2>Stay up to date.</h2><p>English requirements and migration policies can change. Turn on notifications to receive important updates that may affect your preparation.</p><p>Verbo will notify you and update changes automatically after your request to meet new requirements.</p><hr class="divider"><label class="row">Allow Notifications <input class="switch" type="checkbox" data-notify ${state.profile.notifications?'checked':''}></label>`;app.innerHTML=`<main class="onboard desktop-onboard centered-onboard"><div class="on-panel"><header class="on-head"><button class="on-footer-back" data-action="onback">Back</button><div class="brand"><img class="brand-logo" src="assets/icons/logo.png" alt="">Verbo</div><button class="primary" data-action="onnext">Next</button></header><div class="on-progress"><span style="width:${Math.max(0,onStep)*20}%"></span></div><section class="on-body ${onStep===4?'target-step':''} ${onStep===-1?'email-step':''}"><p class="step-caption">${onStep===-1?'Verify your email':`Step ${onStep} of 5`}</p>${body}</section></div></main>`}

function choice(key,val,desc,extra=''){return `<label class="choice ${extra?'target-choice':''} ${state.profile[key]===val?'selected':''}"><input type="radio" name="${key}" data-profile="${key}" value="${val}" ${state.profile[key]===val?'checked':''}><div><strong>${val}</strong><p>${desc}</p>${extra}</div></label>`}
const passage='A city council has launched a six-month cycling pilot. New protected lanes connect residential streets with schools, shops and the railway station.\n\nThe aim is to find out whether safer routes encourage people to make short journeys by bicycle. Residents do not need to own a bike: a local hire scheme offers low-cost rentals.\n\nDuring the trial, the council will measure traffic and collect feedback from residents. These findings will help it decide whether to extend the scheme to other neighbourhoods.';
const announcement='The workshop will now take place in the library hall because more people have registered than expected. Please bring your own laptop. We will start at half past nine.';
const questions={Reading:[['What is the main purpose of the pilot?',['To replace all public transport','To explore whether safer routes encourage cycling','To reduce the number of city parks','To introduce a new parking charge'],1],['Why will the council collect feedback?',['To decide whether to extend the scheme','To select a bus operator','To increase parking','To remove cycle lanes'],0],['Which statement matches the passage?',['The scheme is permanent','Only experienced cyclists can participate','The trial includes routes near schools','Traffic is no longer measured'],2]],Listening:[['Why has the workshop moved?',['The original room is being repaired','More people registered than expected','The speaker requested a different time','The library is closed'],1],['What should participants bring?',['A printed ticket','Their own laptop','A completed report','A library card'],1],['When will the workshop begin?',['9:00 am','9:30 am','10:00 am','10:30 am'],1]],Writing:[['Write a report using the information provided.'],['Some people believe city centres should be car-free. Discuss both views and give your opinion.']],Speaking:[['Which type of transport do you prefer, and why?'],['Describe a place you enjoy visiting.'],['What is one skill you would like to learn?'],['How has technology changed the way people communicate?']]};
function wave(){return `<div class="wave">${[15,28,42,60,40,68,38,22,12].map((h,i)=>`<i style="height:${h}px;animation-delay:${i*.08}s"></i>`).join('')}</div>`}
function startConfirm(m,t){modal('Ready to start?',`<h3>${escape(t)}</h3><p>${m==='Full Test'?'Complete reading, listening, writing and speaking in sequence.':'Answer one question at a time, then submit to see your results.'}</p><div class="notice">Exiting ends this attempt. You cannot resume it later.</div>`,`<button class="primary" data-begin="${m}" data-title="${escape(t)}">Start Test</button>`)}
function begin(m,t){closeModal();attempt={module:m,title:t,seq:m==='Full Test'?['Reading','Listening','Writing','Speaking']:[m],mi:0,qi:0,answers:{},started:Date.now(),seconds:m==='Full Test'?1500:m==='Writing'?600:300,review:false};recordedBlobs={};render();window.scrollTo(0,0);clearInterval(timerId);timerId=setInterval(()=>{if(!attempt)return;attempt.seconds--;const clock=$('#timer');if(clock)clock.textContent=time(attempt.seconds);if(attempt.seconds<=0){clearInterval(timerId);finish();toast('Time is up. Your test has been submitted.')}},1000)}
function time(n){return `${Math.floor(Math.max(0,n)/60)}:${String(Math.max(0,n)%60).padStart(2,'0')}`}
function key(){return attempt.seq[attempt.mi]+'-'+attempt.qi}function answered(a){return a!==undefined&&a!==null&&String(a).trim()!==''}
function tourismChart(){const series=[['Hotels','#5C5FFF',[800,720,650,490,440,390,350,320,280,260,200,180]],['Attractions','#D46B55',[500,400,320,250,200,160,120,100,250,300,360,420]],['Food outlets','#E4AC48',[300,240,190,160,125,100,80,60,130,240,280,320]],['Car hire / taxis','#329C82',[150,120,95,80,65,50,40,35,55,70,80,100]]];const x=i=>64+i*43,y=v=>253-v*.24;return `<figure class="task-chart"><figcaption>Value of international tourism<span>Milton-on-Sea · annual spending (£000)</span></figcaption><svg viewBox="0 0 570 310" role="img" aria-label="Tourism spending over twelve years. Hotels decline while other sectors recover after Year 8. Years 11 and 12 are projections.">${[0,200,400,600,800].map(v=>`<path d="M64 ${y(v)}H537" stroke="#E9E9F0"/><text x="50" y="${y(v)+4}" text-anchor="end" fill="#777781" font-size="12">${v}</text>`).join('')}<path d="M451 35V253" stroke="#CACBFF" stroke-dasharray="4 5"/>${series.map(([n,c,v])=>`<polyline points="${v.slice(0,10).map((v,i)=>x(i)+','+y(v)).join(' ')}" fill="none" stroke="${c}" stroke-width="3" stroke-linejoin="round"/><polyline points="${v.slice(9).map((v,i)=>x(i+9)+','+y(v)).join(' ')}" fill="none" stroke="${c}" stroke-width="3" stroke-dasharray="4 5"/>`).join('')}${Array.from({length:12},(_,i)=>`<text x="${x(i)}" y="277" text-anchor="middle" fill="#777781" font-size="12">${i+1}</text>`).join('')}<text x="300" y="303" text-anchor="middle" fill="#777781" font-size="12">Year · dashed lines show projections</text></svg><div class="chart-legend">${series.map(([n,c])=>`<span><i style="background:${c}"></i>${n}</span>`).join('')}</div></figure>`}
function renderTest(){if(attempt.review){finish();return}const m=attempt.seq[attempt.mi],q=questions[m][attempt.qi],val=attempt.answers[key()],count=questions[m].length;let left='',right='';if(m==='Reading')left=`<small class="purple">Passage · Questions 1–3</small><h3>A different way to get around</h3><p class="passage">${passage.replaceAll('\n\n','</p><p class="passage">')}</p>`;if(m==='Listening')left=`<small class="purple">Audio · Questions 1–3</small><h3>A workshop announcement</h3><p>Listen to the announcement, then answer each question. You can replay the audio in this practice set.</p><div class="audio-panel">${wave()}<div class="bar"><span style="width:0%" id="audio-progress"></span></div><button data-action="playaudio">Play audio</button></div>`;if(m==='Writing')left=attempt.qi===0?`<small class="purple">Passage</small><h3>International Tourism</h3><p class="passage">The tourist board of Milton-on-Sea collects data to establish the value of international tourism to the town in four sectors. Write a report on the changing value of tourism.</p><p>Describe the main trends, explain possible changes since Year 8, and discuss the predictions for Years 11 and 12.</p>${tourismChart()}`:`<small class="purple">Task 2</small><h3>Develop a clear argument</h3><p class="passage">${q[0]}</p><p>Include reasons and examples. Finish with a clear conclusion.</p>`;if(m==='Speaking')left=`<small class="purple">Prompt</small><h3>${q[0]}</h3><p>Take a moment to prepare.</p><div class="notice">Suggested response: 45–60 seconds</div>`;
if(['Reading','Listening'].includes(m))right=`<small class="purple">Question ${attempt.qi+1}</small><h3>${q[0]}</h3><small>Choose one answer</small>${q[1].map((a,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" ${val===i?'checked':''}>${a}</label>`).join('')}`;
if(m==='Writing')right=`<small class="purple">Question ${attempt.qi+1}</small><h3>${q[0]}</h3><p>Support your ideas with evidence and organise your response clearly.</p><label for="writing" class="muted">Your response</label><textarea class="editor" id="writing" placeholder="Start typing here…">${escape(val||'')}</textarea><small id="wordcount">${String(val||'').trim().split(/\s+/).filter(Boolean).length} words</small>`;
if(m==='Speaking')right=`<small class="purple">Question ${attempt.qi+1}</small><h3>Record your response</h3><p>Give your answer and explain your reasons. Include an example from your own experience.</p><div class="audio-panel">${wave()}<p id="recordstatus">${val?'Response recorded':'Ready when you are'}</p><button class="primary" data-action="record">${icon('Mic')} ${val?'Record again':'Start recording'}</button>${recordedBlobs[key()]?`<audio style="width:100%;margin-top:15px" controls src="${recordedBlobs[key()]}"></audio>`:''}</div><button class="link" data-action="sample-response">Use a sample response</button>`;
app.innerHTML=`<div class="test-shell"><header class="test-head"><button data-action="exit-test">Exit</button><div><h3>${escape(attempt.title)}</h3><small>${m} · ${attempt.module==='Full Test'?'Module '+(attempt.mi+1)+' of 4 · ':''}Question ${attempt.qi+1} of ${count}</small></div><div class="timer">Time Left <span id="timer">${time(attempt.seconds)}</span></div></header><div class="test-progress"><span style="width:${(attempt.qi+1)/count*100}%"></span></div><button class="source-toggle" data-action="toggle-source">Show / hide ${m==='Reading'?'passage':'prompt'}</button><div class="test-layout"><section class="panel source">${left}</section><section class="panel response-panel">${right}</section></div><footer class="test-footer"><button data-action="previous" ${attempt.qi===0?'disabled':''}>Previous</button><small>${Object.keys(attempt.answers).filter(k=>k.startsWith(m)&&answered(attempt.answers[k])).length} of ${count} answered</small><button class="primary" id="nextanswer" data-action="next">${attempt.qi===count-1?(attempt.mi===attempt.seq.length-1?'Submit Test':'Next module'):'Next'}</button></footer></div>`}
function finish(){clearInterval(timerId);stopRecording();speechSynthesis?.cancel();const scores={};attempt.seq.forEach(m=>{scores[m]=['Reading','Listening'].includes(m)?Math.round(questions[m].filter((q,i)=>attempt.answers[m+'-'+i]===q[2]).length/questions[m].length*100):null});const result={title:attempt.title,module:attempt.module,full:attempt.module==='Full Test',date:'Today',score:Object.values(scores).every(v=>v!=null)?Math.round(Object.values(scores).reduce((a,b)=>a+b,0)/Object.values(scores).length):null,scores,elapsed:time(Math.floor((Date.now()-attempt.started)/1000)),answers:attempt.answers};state.history.unshift(result);persist();attempt=null;page='Results';currentReport=result;tab=result.module;render();window.scrollTo(0,0);toast('Test submitted. Your results are ready.')}
function reviewPassage(m,i){let label='',body='';if(m==='Reading'&&i===0){label='Passage - Questions 1–'+questions[m].length;body='<h3>A different way to get around</h3><p>'+escape(passage).replaceAll('\n\n','</p><p>')+'</p>';}if(m==='Listening'&&i===0){label='Transcript - Questions 1–'+questions[m].length;body='<h3>A workshop announcement</h3><p>'+escape(announcement)+'</p>';}if(m==='Writing'){label='Passage - Question '+(i+1);body=i===0?'<h3>International Tourism</h3><p>The tourist board of Milton-on-Sea collects data to establish the value of international tourism to the town in four sectors. Write a report on the changing value of tourism.</p><p>Describe the main trends, explain possible changes since Year 8, and discuss the predictions for Years 11 and 12.</p>'+tourismChart():'<h3>Develop a clear argument</h3><p>'+escape(questions[m][i][0])+'</p><p>Include reasons and examples. Finish with a clear conclusion.</p>';}return label?`<details class="review-source grouped-source"><summary>${label} ${chev()}</summary><div class="review-source-body">${body}</div></details>`:'';}
function answerReview(r,m){
 const objective=['Reading','Listening'].includes(m), demo=!r.answers;
 if(demo&&m==='Speaking')return `<h3>${m} feedback</h3><p>${feedback[m][0]}</p>`;
 return `<section class="question-review">${questions[m].map((q,i)=>{
 const a=demo?(i===1?(q[2]+1)%q[1].length:q[2]):r.answers[m+'-'+i], correct=a===q[2], empty=a===undefined||a===null||a==='';
 return `${reviewPassage(m,i)}<article class="question-card"><div class="question-meta"><span>QUESTION ${i+1}</span><span class="review-status ${empty?'unanswered':correct?'is-correct':'needs-review'}">${objective?(empty?'Unanswered':correct?'<i class="review-tick" aria-hidden="true"></i>Correct':'Incorrect'):'Response'}</span></div><h3>${escape(q[0])}</h3><div class="question-columns ${objective?'multiple-choice-review':''}"><div>${objective?`<span class="review-label">Answer options</span><div class="review-options">${q[1].map((option,j)=>`<div class="review-option ${j===q[2]?'option-correct':j===a?'option-incorrect':''}"><span class="option-letter">${String.fromCharCode(65+j)}</span><span>${escape(option)}</span>${j===q[2]?`<small><i class="review-tick" aria-hidden="true"></i>${j===a?'Your choice':'Correct answer'}</small>`:j===a?'<small>Your choice</small>':''}</div>`).join('')}</div>`:`<p class="written-response">${m==='Writing'?escape(a||'No response submitted'):a?'Response completed':'No response submitted'}</p>`}</div>${objective?'':`<aside class="answer-comparison"><span class="review-label">Your answer</span><p>${a?'Submitted':'Not submitted'}</p><p class="muted">An assessed score has not been generated.</p></aside>`}</div></article>`;
 }).join('')}</section>`;
}

async function record(){if(recording){stopRecording();return}try{audioStream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(audioStream);const chunks=[],k=key();recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{recordedBlobs[k]=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));if(attempt){attempt.answers[k]='recorded';renderTest()}};recorder.start();recording=true;$('#recordstatus').textContent='Recording…';document.querySelector('[data-action="record"]').textContent='Stop recording';$('.wave').classList.add('playing')}catch{toast('Microphone unavailable. Allow access or use a sample response.')}}
function stopRecording(){if(recorder&&recorder.state!=='inactive')recorder.stop();audioStream?.getTracks().forEach(t=>t.stop());recording=false}
function resource(i=0){modal(resourceNames[i],`<img src="assets/${resourceImages[i]}" style="width:100%;border-radius:9px" alt=""><h3 style="margin-top:18px">${['Connect your ideas','Listen for key details','Build a clear paragraph','Make the most of your tutor session','Get familiar with test day'][i]}</h3><p>${['Start with your main point, give a reason, then add a specific example. Use “Another advantage is” to link a second idea.','Listen once for the main message. Listen again for times, names and instructions. Check the whole phrase before answering.','Give each paragraph one main idea. Explain your point, support it with evidence and connect it to the question.','Bring one speaking goal and an example you would like feedback on. After the session, review your tutor’s notes and choose one action to practise.','Review the order of the four modules and read each task’s instructions. Set up a quiet space and check your audio before beginning a full mock.'][i]}</p>`,`<button class="primary" data-resource-open="${i}">${i===2?'Read':'Watch'}</button>`)}
const bookingTutors=[['Susan Walsh','Speaking mentor','susan.svg'],['Damien Strand','Reading & writing tutor','damien-writing.svg'],['Kriti K','Listening tutor','kriti.svg']];
let calendarMonth=new Date();
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function bookingSelect(id,label,options){return `<label id="${id}-label">${label}</label><div class="booking-dropdown"><input type="hidden" id="${id}" value="${options[0][0]}"><button type="button" class="secondary study-trigger" data-book-menu="${id}" aria-labelledby="${id}-label ${id}-value" aria-expanded="false"><span id="${id}-value">${options[0][1]}</span>${chev()}</button><div class="study-options booking-menu" id="${id}-menu" hidden>${options.map(([value,html],i)=>`<button type="button" data-book-select="${id}" data-value="${value}" aria-pressed="${i===0}"><span>${html}</span><i class="booking-radio"></i></button>`).join('')}</div></div>`}
function calendarHTML(){const first=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1),start=new Date(first);start.setDate(1-(first.getDay()+6)%7);const today=localDate(new Date()),selected=$('#bookdate').value;return `<div class="row calendar-heading"><button type="button" class="plain" data-calendar-month="-1" aria-label="Previous month">${chev('left')}</button><span>${first.toLocaleDateString('en-AU',{month:'long',year:'numeric'})}</span><button type="button" class="plain" data-calendar-month="1" aria-label="Next month">${chev('right')}</button></div><div class="row calendar-input"><input aria-label="Selected date" value="${new Date(selected+'T00:00:00').toLocaleDateString('en-AU')}" readonly><button type="button" class="secondary" data-calendar-today>Today</button></div><div class="calendar-grid">${['Mo','Tu','We','Th','Fr','Sa','Su'].map(d=>`<span>${d}</span>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const value=localDate(d);return `<button type="button" data-calendar-date="${value}" aria-label="${d.toLocaleDateString('en-AU',{day:'numeric',month:'long',year:'numeric'})}" aria-pressed="${value===selected}" class="${d.getMonth()!==first.getMonth()?'outside ':''}${value===selected?'chosen ':''}${value===today?'is-today':''}" ${value<today?'disabled':''}>${d.getDate()}</button>`}).join('')}</div>`}
function booking(){const today=localDate(new Date());calendarMonth=new Date();modal('Book a session',`<p class="booking-intro">Choose your tutor and a time that works for you.</p><form class="form booking-workspace" id="booking-form"><section class="booking-details"><h3>Session details</h3><div class="booking-field">${bookingSelect('bookmodule','Module',['Speaking','Writing','Reading','Listening'].map(x=>[x,x]))}</div><div class="booking-field">${bookingSelect('booktutor','Select tutor',bookingTutors.map(t=>[t[0],`<span class="booking-person"><img src="assets/${t[2]}" alt=""><span>${t[0]}<small>${t[1]}</small></span></span>`]))}</div><div class="booking-field"><label for="bookfocus">What would you like to work on?</label><textarea id="bookfocus">Linking ideas and speaking fluently.</textarea></div></section><section class="booking-availability"><h3>Choose a date & time</h3><input type="hidden" id="bookdate" value="${today}"><span id="bookdate-value" class="booking-selected-date">${new Date().toLocaleDateString('en-AU',{weekday:'long',day:'numeric',month:'long'})}</span><div class="booking-calendar inline-calendar" id="bookdate-menu"></div><label>Available times · Melbourne</label><input type="hidden" id="booktime" value="1:00PM – 1:15PM"><div class="booking-time-slots">${['1:00PM – 1:15PM','4:00PM – 4:15PM','5:00PM – 5:15PM'].map((t,i)=>`<button type="button" data-book-slot="${t}" aria-pressed="${i===0}">${t}</button>`).join('')}</div></section><div class="booking-footer"><span class="muted">One-on-one · 15 minutes</span><button class="primary" type="submit">Book Session</button></div></form>`,' ');$('#bookdate-menu').innerHTML=calendarHTML()}
function closeBookingMenus(){document.querySelectorAll('.booking-menu,.booking-calendar:not(.inline-calendar)').forEach(m=>m.hidden=true);document.querySelectorAll('[data-book-menu]').forEach(b=>b.setAttribute('aria-expanded','false'))}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!e.target.closest('.booking-dropdown'))closeBookingMenus();if(!b)return;const d=b.dataset;if(d.bookSlot){$('#booktime').value=d.bookSlot;document.querySelectorAll('[data-book-slot]').forEach(o=>o.setAttribute('aria-pressed',String(o===b)));}if(d.bookMenu){const m=document.getElementById(d.bookMenu+'-menu'),open=m.hidden;closeBookingMenus();m.hidden=!open;b.setAttribute('aria-expanded',String(open))}if(d.bookSelect){const input=document.getElementById(d.bookSelect);input.value=d.value;document.getElementById(d.bookSelect+'-value').innerHTML=b.firstElementChild.innerHTML;document.querySelectorAll(`[data-book-select="${d.bookSelect}"]`).forEach(o=>o.setAttribute('aria-pressed',String(o===b)));closeBookingMenus();document.querySelector(`[data-book-menu="${d.bookSelect}"]`).focus()}if(d.calendarMonth){calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+Number(d.calendarMonth),1);$('#bookdate-menu').innerHTML=calendarHTML()}if(d.calendarDate||'calendarToday'in d){const value=d.calendarDate||localDate(new Date());$('#bookdate').value=value;calendarMonth=new Date(value+'T00:00:00');$('#bookdate-value').textContent=calendarMonth.toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'});$('#bookdate-menu').innerHTML=calendarHTML()}if('calendarApply'in d){closeBookingMenus();document.querySelector('[data-book-menu="bookdate"]').focus()}});
document.addEventListener('keydown',e=>{if(!e.target.closest('.booking-dropdown'))return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();const trigger=e.target.closest('.booking-dropdown').querySelector('[data-book-menu]');closeBookingMenus();trigger.focus()}if(['ArrowDown','ArrowUp'].includes(e.key)){const menu=e.target.closest('.booking-dropdown').querySelector('.booking-menu:not([hidden])');if(!menu)return;e.preventDefault();const opts=[...menu.querySelectorAll('button')],i=opts.indexOf(document.activeElement);opts[(i+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length].focus()}},true);

document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login-form'){onStep=-1;onboard()}if(e.target.id==='booking-form'){state.bookings.push({module:$('#bookmodule').value,date:$('#bookdate').value,time:$('#bookdate').value+' · '+$('#booktime').value,tutor:$('#booktutor').value,focus:$('#bookfocus').value});persist();closeModal();page='Learning';render();toast('Session added to your schedule.')}});
document.addEventListener('change',e=>{if(e.target.dataset.task!==undefined){state.tasks[+e.target.dataset.task].done=e.target.checked;persist();render()}if(e.target.dataset.profile){state.profile[e.target.dataset.profile]=e.target.value;onboard()}if(e.target.hasAttribute('data-notify'))state.profile.notifications=e.target.checked;if(e.target.name==='answer'&&attempt){attempt.answers[key()]=+e.target.value;renderTest()}});
document.addEventListener('input',e=>{if(e.target.id==='writing'&&attempt){attempt.answers[key()]=e.target.value;$('#wordcount').textContent=e.target.value.trim().split(/\s+/).filter(Boolean).length+' words'}if(e.target.id==='country-search'){const val=e.target.value.toLowerCase();document.querySelectorAll('[data-country]').forEach(b=>b.hidden=!b.dataset.country.toLowerCase().includes(val));$('#country-empty').hidden=!!document.querySelector('[data-country]:not([hidden])')}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.scheduleRange){scheduleRange=d.scheduleRange;render();document.querySelector('.schedule-dropdown .study-trigger')?.focus();return}if(d.removeFilter){testFilters.delete(d.removeFilter);render();return}if(d.studyGoal){state.profile.studyGoal=d.studyGoal;persist();render();document.querySelector('.study-trigger')?.focus();return}if(d.carousel){(d.carouselTarget?document.querySelector('#'+d.carouselTarget+' .carousel')||document.getElementById(d.carouselTarget):$('#report-carousel')).scrollBy({left:Number(d.carousel)*320,behavior:'smooth'});return}if(d.settingsDemo){toast(d.settingsDemo+' preview — no account changes are made.');return}if(d.onstep){onStep=+d.onstep;onboard();return}if(d.billing){billing=d.billing;render();return}if(d.plan){const p=plans.find(p=>p.name===d.plan);modal('Make room for progress.',`<span class="pill purple">${p.name} · ${billing==='yearly'?'Yearly':'Monthly'}</span><h3 style="margin-top:28px">Your next chapter starts here.</h3><p>${p.description} Your plan includes ${p.features[0].toLowerCase()}.</p><div class="notice">This is a prototype. No payment details are needed and you won’t be charged.</div>`,`<button data-action="close">Keep exploring</button><button class="primary" data-confirm-plan="${p.name}">Use ${p.name} in demo ${chev('right')}</button>`);return}if(d.confirmPlan){state.plan=d.confirmPlan;persist();closeModal();render();toast('Demo plan updated. No payment was taken.');return}if(d.nav){navigate(d.nav);return}if(d.tab){tab=d.tab;render();return}if(d.clear){if(d.clear==='difficulty')difficulty='';else status='';render();return}if(d.start){startConfirm(d.start,d.title);return}if(d.begin){begin(d.begin,d.title);return}if(d.report!==undefined){currentReport=[...state.history,...(state.freshStart?[]:seedHistory)][+d.report];render();window.scrollTo(0,0);return}if(d.historyTab){historyTab=d.historyTab;render();return}if(d.resource!==undefined){resource(+d.resource);return}if(d.schedule){if(!state.tasks.some(t=>t.name===d.schedule)){state.tasks.push({name:d.schedule,duration:'10 mins',done:false,type:'resource'});persist();toast('Added to this week’s tasks.')}else toast('Already in your weekly tasks.');return}if(d.taskOpen!==undefined){const t=state.tasks[+d.taskOpen];if(t.type==='booking')booking();else if(t.type==='resource'||t.type==='notes')resource(0);else navigate('Tests');return}if(d.country){state.profile.country=d.country;onboard();$('#country').focus();return}if(d.reviewQ){[attempt.mi,attempt.qi]=d.reviewQ.split(',').map(Number);attempt.review=false;renderTest();return}if(d.join){modal(d.join,'<p>Your speaking session with Susan Walsh is ready.</p><p>Bring one question you would like to work on. Your recent feedback is available in Class History.</p><div class="notice">This prototype does not connect to a live call.</div>');return}
if(d.resourceOpen!==undefined){const i=Number(d.resourceOpen);modal(resourceNames[i],i===2?'<h3>Build a clear paragraph</h3><p>Start with one main idea. Explain it, support it with a specific example, then connect it to the question.</p><p>Use a separate paragraph for each new point. Finish by checking that every sentence supports your argument.</p>':'<div class="empty"><img class="empty-state-art" src="assets/'+resourceImages[i]+'" alt=""><p>This video is a preview resource. Playback is not connected in this prototype.</p></div>','');return;}if(d.lectureTranscript!==undefined){const i=Number(d.lectureTranscript);modal(lectureTitles[i],'<p>In this lecture, we focus on organising a clear response. Begin with your main idea, explain it with a practical reason, and add a specific example. Review your work for clarity and repetition.</p>');return;}if(d.lecturePlay!==undefined){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance('In this lecture, we focus on organising a clear response. Begin with your main idea, explain it with a practical reason, and add a specific example. Review your work for clarity and repetition.'));return;}if(d.note!==undefined){currentNote=Number(d.note);render();window.scrollTo(0,0);return;}switch(d.action){case'help-unavailable':modal('Not available in this prototype','<p class="help-unavailable-message">This support feature is not available in this prototype.</p>','<button class="primary" data-action="close">Close</button>');break;case'backnotes':currentNote=null;historyTab='Notes';render();document.querySelector('.learning-history')?.scrollIntoView({block:'start'});break;case'schedule-toggle':{const m=$('#schedule-options');m.hidden=!m.hidden;b.setAttribute('aria-expanded',String(!m.hidden));break;}case'test-filter-toggle':testFilterOpen=!testFilterOpen;render();break;case'clear-test-filters':testFilters.clear();render();break;case'study-toggle':{const trigger=document.querySelector('.study-trigger'),menu=$('#study-options');menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));break;}case'all-learning-resources':modal('Your resource library',`<div class="stack">${resourceNames.map((name,i)=>`<button class="secondary" data-resource="${i}">${escape(name)} ${chev('right')}</button>`).join('')}</div>`);break;case'schedule-day':modal('Today’s schedule','<p>These are your upcoming demo sessions for today. Use the chevrons to browse your schedule.</p>');break;case'mentor-transcript':modal('Mentor feedback transcript','<p>You answered directly and supported your preference with practical reasons. The ideas are relevant, but the pauses make them sound separate. Try a linking phrase before adding your next point.</p>');break;case'samplereport':currentReport=seedHistory[0];render();break;case'savepreferences':state.preferences=Object.fromEntries([...document.querySelectorAll('[data-pref]')].map(e=>[e.dataset.pref,e.checked]));persist();toast('Demo preferences saved. No notifications will be sent.');break;case'close':closeModal();break;case'demo':state.onboarded=true;persist();render();break;case'signup':onStep=-1;onboard();break;case'forgot':modal('Reset your password','<p>Account recovery is not connected in this prototype. Use Explore Verbo to continue without an account.</p>');break;case'onback':onStep=onStep===-1?0:onStep===1?-1:onStep-1;onboard();break;case'onnext':if(onStep===-1){onStep=1;onboard();break;}if(onStep<5){onStep++;onboard()}else{state.onboarded=true;state.freshStart=true;state.history=[];state.tasks=[];state.bookings=[];page='Dashboard';persist();render();modal('Welcome to Verbo, '+escape(state.profile.name)+'!',`<img class="welcome-art" src="assets/welcome-generic.svg" alt=""><p>Your ${escape(state.profile.exam)} preparation starts here. Take your first test to understand your starting point, then build a plan around your results.</p>`,`<button class="primary" data-action="close">Explore my dashboard ${chev('right')}</button>`)}window.scrollTo(0,0);break;case'countries':{const menu=$('#country-menu');menu.hidden=!menu.hidden;b.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)$('#country-search').focus();break;}case'saveprofile':state.profile.name=$('#profile-name').value.trim()||'Rahul';state.profile.notifications=$('#profile-notifications').checked;persist();toast('Profile updated.');break;case'restartonboarding':state.onboarded=false;onStep=1;render();break;case'logout':state.onboarded=false;persist();onStep=0;render();break;case'notifications':modal('Notifications',state.profile.notifications?'<p>Your next speaking session is ready to join.</p><p>New feedback is available in your test history.</p>':'<p>Notifications are turned off. You can enable them in Settings.</p>');break;case'score-info':modal('About your progress','<p>Dashboard cards show recent practice performance. Full mock results show the scores from that individual attempt.</p><p>The supplied scores, levels and targets are illustrative prototype data. They are not official exam predictions.</p>');break;case'plans':modal('Verbo Plus','<p>Includes module tests, full mocks, resources and tutor session history.</p><p>No payment or subscription changes are made in this prototype.</p>');break;case'filter':modal('Filter tests',`<div class="form"><label>Difficulty</label><select id="filter-level">${['All','Hard','Medium','Easy'].map(x=>`<option ${x===(difficulty||'All')?'selected':''}>${x}</option>`).join('')}</select><label>Status</label><select id="filter-status">${['All','New','Completed'].map(x=>`<option ${x===(status||'All')?'selected':''}>${x}</option>`).join('')}</select></div>`,'<button data-action="close">Cancel</button><button class="primary" data-action="applyfilters">Apply filters</button>');break;case'applyfilters':difficulty=$('#filter-level').value==='All'?'':$('#filter-level').value;status=$('#filter-status').value==='All'?'':$('#filter-status').value;closeModal();render();break;case'resetfilters':difficulty='';status='';render();break;case'booking':booking();break;case'backresults':currentReport=null;render();break;case'expandall':{const all=[...document.querySelectorAll('.module-detail')];const open=!all.every(x=>x.open);all.forEach(x=>x.open=open);b.innerHTML=(open?'Collapse All':'Expand All')+' '+chev(open?'up':'down');break;}case'scheduleall':resourceNames.forEach(name=>{if(!state.tasks.some(t=>t.name===name))state.tasks.push({name,duration:'10 mins',done:false,type:'resource'})});persist();toast('Recommended practice added to your weekly tasks.');break;case'toggle-source':$('.source').classList.toggle('folded');break;case'previous':stopRecording();attempt.qi=Math.max(0,attempt.qi-1);renderTest();break;case'next':if(recording){toast('Stop recording before moving on.');return}speechSynthesis?.cancel();if(attempt.qi<questions[attempt.seq[attempt.mi]].length-1)attempt.qi++;else if(attempt.mi<attempt.seq.length-1){attempt.mi++;attempt.qi=0}else{finish();break;}renderTest();window.scrollTo(0,0);break;case'exit-test':modal('Exit this test?','<p>Your current answers will be discarded. You cannot resume this attempt.</p>','<button data-action="close">Stay in test</button><button class="primary" data-action="confirmexit">Exit test</button>');break;case'confirmexit':clearInterval(timerId);stopRecording();attempt=null;speechSynthesis?.cancel();closeModal();page='Tests';tab='Reading';render();toast('Attempt ended.');break;case'submit-test':finish();break;case'playaudio':if(!('speechSynthesis'in window)){toast('Audio is unavailable in this browser.');break}if(speechSynthesis.speaking){speechSynthesis.cancel();b.textContent='Play audio';$('.wave')?.classList.remove('playing')}else{const utterance=new SpeechSynthesisUtterance(announcement);utterance.lang='en-GB';utterance.rate=.9;utterance.onend=()=>{b.textContent='Play audio';$('.wave')?.classList.remove('playing')};speechSynthesis.speak(utterance);b.textContent='Stop audio';$('.wave')?.classList.add('playing')}break;case'record':record();break;case'sample-response':attempt.answers[key()]='sample response';renderTest();toast('Sample response added.');break;case'mentor-play':{const u=new SpeechSynthesisUtterance('You answered directly and supported your preference with practical reasons. Try a linking phrase before adding your next point.');speechSynthesis.cancel();speechSynthesis.speak(u);break}}
});
