document.addEventListener('focusout',e=>{if(e.target.id==='email')e.target.value='rahul@example.com';if(e.target.id==='password')e.target.value='VerboDemo123!';});

function freshDashboard(){const count=state.history.length;const current=Object.fromEntries(Object.keys(rates).map(m=>[m,state.history.find(r=>r.scores?.[m]!=null)?.scores[m]||0]));return `<h2 class="greeting">${count?'Keep going':'Welcome'}, <span class="purple">${escape(state.profile.name)}.</span></h2><p class="page-subtitle">${count?'Every practice session helps you understand your next step.':'Your journey starts here. Take your first test to find your starting point.'}</p><h3>Your Progress</h3><div class="dashboard-grid"><div><div class="scores">${Object.entries(current).map(([m,v])=>`<article class="panel scorecard"><h3>${m}</h3><div class="score">${v}% <small>/ ${targets[m]}%</small></div><div class="bar"><span style="width:${Math.min(v/targets[m]*100,100)}%"></span></div><small>${state.history.some(r=>r.scores?.[m]!=null)?'Latest assessed test':'No tests completed yet'}</small></article>`).join('')}</div><section class="panel empty-progress"><h3>Your progress over time</h3><div class="empty-chart"><img class="empty-state-art" src="assets/empty-progress.svg" alt=""><span>0%</span><p>Your progress chart will build as you complete tests.</p></div><button class="link" data-nav="Results">View test history ${chev('right')}</button></section></div><div class="stack"><section class="panel"><h3>Your first step</h3><h2>Find your starting point.</h2><p>Try a practice test. Your results will help you choose what to work on next.</p><button class="primary" data-nav="Tests">Explore tests ${chev('right')}</button></section><section class="panel"><h3>Weekly Test Streak</h3><h2 class="task-title">${count?1:0} ${count?'Day':'Days'}</h2><div class="panel black row">Tests Completed <strong>${count}/10</strong></div><div class="week">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}</div></section><section class="panel"><h3>Your weekly tasks</h3>${!state.tasks.length?'<img class="empty-state-art" src="assets/empty-tasks.svg" alt="">':''}<p>${state.tasks.filter(t=>t.done).length} of ${state.tasks.length} tasks completed</p><p class="muted">Add recommended practice after reviewing your first result.</p></section></div></div>`}

document.addEventListener('click',e=>{if(!e.target.closest('.study-dropdown')){const menu=document.getElementById('study-options');if(menu){menu.hidden=true;document.querySelector('.study-trigger').setAttribute('aria-expanded','false')}}});
document.addEventListener('keydown',e=>{const menu=document.getElementById('study-options');if(!menu||menu.hidden)return;if(e.key==='Escape'){menu.hidden=true;const t=document.querySelector('.study-trigger');t.setAttribute('aria-expanded','false');t.focus()}if(['ArrowDown','ArrowUp'].includes(e.key)&&e.target.closest('.study-dropdown')){e.preventDefault();const options=[...menu.querySelectorAll('button')],i=options.indexOf(document.activeElement);options[(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length].focus()}});

document.addEventListener('change',e=>{const value=e.target.dataset.testFilter;if(!value)return;e.target.checked?testFilters.add(value):testFilters.delete(value);render();document.querySelector(`[data-test-filter="${value}"]`)?.focus()});
document.addEventListener('click',e=>{if(testFilterOpen&&!e.target.closest('.test-filter')&&!e.target.closest('[data-remove-filter]')){testFilterOpen=false;const menu=$('#test-filter-options');if(menu){menu.hidden=true;document.querySelector('[data-action="test-filter-toggle"]').setAttribute('aria-expanded','false')}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&testFilterOpen){testFilterOpen=false;const menu=$('#test-filter-options');if(menu){menu.hidden=true;const trigger=document.querySelector('[data-action="test-filter-toggle"]');trigger.setAttribute('aria-expanded','false');trigger.focus()}}});

document.addEventListener('click',e=>{if(!e.target.closest('.schedule-dropdown')){const m=$('#schedule-options');if(m){m.hidden=true;document.querySelector('.schedule-dropdown .study-trigger')?.setAttribute('aria-expanded','false')}}});
document.addEventListener('keydown',e=>{const m=$('#schedule-options');if(!m||m.hidden)return;const t=document.querySelector('.schedule-dropdown .study-trigger');if(e.key==='Escape'){m.hidden=true;t.setAttribute('aria-expanded','false');t.focus()}if(['ArrowDown','ArrowUp'].includes(e.key)&&e.target.closest('.schedule-dropdown')){e.preventDefault();const opts=[...m.querySelectorAll('button')],i=opts.indexOf(document.activeElement);opts[(i+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length].focus()}});
